import html
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
evidence = json.loads((ROOT / 'evidence/warehouse_examples.json').read_text())
css = '''*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#142236;font:18px/1.5 -apple-system,BlinkMacSystemFont,Arial,sans-serif}main{max-width:1480px;margin:0 auto;padding:32px 42px}small,.eyebrow{font-size:14px;letter-spacing:2px;text-transform:uppercase;color:#41617c}.eyebrow{color:#047c78;font-weight:700}h1{font-size:45px;line-height:1.12;margin:12px 0 18px;letter-spacing:-2px}h2{font-size:27px;line-height:1.2;margin:0 0 15px}p{margin:10px 0;color:#4c5e71}.lead{max-width:1050px;font-size:21px}.stats,.flow,.cards{display:grid;gap:18px;margin:24px 0}.stats{grid-template-columns:repeat(4,1fr)}.stat,.node,.card{background:white;border:1px solid #d9e1ea;border-radius:18px;padding:20px}.stat strong{display:block;font-size:37px;color:#142236}.stat span{font-size:15px;color:#53687b}.flow{grid-template-columns:repeat(4,1fr)}.node{border-top:5px solid #088a85}.node b{display:block;font-size:20px}.node i{display:block;font-style:normal;color:#00776e;font-size:14px;margin-top:12px}.cards{grid-template-columns:repeat(3,1fr)}.card{padding:22px}.tag{display:inline-block;background:#e3f3ee;border-radius:20px;color:#146844;padding:5px 12px;font-size:14px;font-weight:700}.negative{background:#fce7e7;color:#aa3434}.neutral{background:#ecedf2;color:#4a566b}blockquote{margin:23px 0;min-height:82px;font-size:23px;line-height:1.4;color:#182c43}.details{border-top:1px solid #e2e8f0;padding-top:18px;font-size:17px}.details div{margin:8px 0}.details b{display:inline-block;min-width:100px}footer{margin-top:10px;padding-top:8px;border-top:1px solid #cbd6e1;color:#5b6c7d;font-size:13px;line-height:1.35}code{font-size:14px}table{width:100%;border-collapse:collapse;font-size:17px;background:white}td,th{text-align:left;padding:13px 18px;border-bottom:1px solid #dce3ea}th{background:#deebe9}a{color:#087e78}'''


def page(name, title, body):
    (ROOT / 'showcase' / name).write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><title>{title}</title><style>{css}</style><main>{body}</main></html>')


page('overview.html', 'Zomato AI data pipeline', '''
<div class="eyebrow">Portfolio project · verified 13 November 2026</div>
<h1>From raw files to analytics<br>and three bounded AI features</h1>
<p class="lead">An end-to-end learning project built from Darshil Parmar’s Zomato tutorial, with reproducible Docker orchestration, dbt documentation, application query guards and shared AI credit controls.</p>
<div class="stats"><div class="stat"><strong>10 million</strong><span>orders in the warehouse</span></div><div class="stat"><strong>23.0 million</strong><span>order items · exact: 22,998,179</span></div><div class="stat"><strong>17 models</strong><span>144 documented columns</span></div><div class="stat"><strong>28 checks</strong><span>dbt data tests passed</span></div></div>
<h2>One manual Airflow run · all four tasks passed</h2>
<div class="flow"><div class="node"><small>01 / Ingest</small><b>Private S3 → Snowflake RAW</b><p>Seven CSV sources, authenticated stage and COPY loading.</p><i>reload_raw ✓</i></div><div class="node"><small>02 / Transform</small><b>dbt staging → marts</b><p>Typed staging, dimensions, incremental facts and analytics marts.</p><i>dbt_build_core ✓ · PASS 32</i></div><div class="node"><small>03 / Enrich</small><b>Structured review analysis</b><p>Five generated review examples with validated sentiment, topic and issue.</p><i>enrich_reviews ✓ · 5 saved</i></div><div class="node"><small>04 / Analyze</small><b>Review insights mart</b><p>Aggregate the enriched sample by city, topic and sentiment.</p><i>dbt_build_ai ✓ · PASS 13</i></div></div>
<div class="cards"><div class="card"><h2>Review enrichment</h2><p>Schema-checked labels, versioned cache and warehouse MERGE.</p></div><div class="card"><h2>Review RAG</h2><p>100-review saved corpus, hosted embeddings, five retrieved excerpts and checked review-ID citations.</p></div><div class="card"><h2>Text to SQL</h2><p>Generate → inspect → run. Allowlisted marts, SQL AST checks, 100-row cap and 30-second timeout.</p></div></div>
<footer>Saved verification overview, not a live monitoring page. Tutorial-generated facts and review text; no production or customer-impact claim. AI coding tools assisted implementation. Final run: 18:51:48–18:52:32 UTC.</footer>''')

cards = []
for row in evidence['enrichment_examples'][:3]:
    label = row['SENTIMENT_LABEL']
    cards.append(f'''<article class="card"><small>Review {html.escape(row['REVIEW_ID'])}</small><h2 style="margin-top:12px">{label.capitalize()} example</h2><span class="tag {label}">{label.upper()}</span><blockquote>“{html.escape(row['COMMENT'])}”</blockquote><div class="details"><div><b>Score</b>{row['SENTIMENT_SCORE']:+.1f}</div><div><b>Topic</b>{html.escape(row['TOPIC'])}</div><div><b>Key issue</b>{html.escape(row['KEY_ISSUE'] or 'None returned')}</div><div><b>Model</b>gpt-4o-mini</div></div></article>''')
page('enrichment.html', 'Verified review enrichment examples', '''<div class="eyebrow">Feature 01 · saved Snowflake output</div><h1>Turn review text into<br>structured analytics fields</h1><p class="lead">Three distinct examples from the five-row enriched sample saved by the successful final Airflow run. These are tutorial-generated review texts, not observed customer research.</p><div class="cards">''' + ''.join(cards) + '''</div><h2>Validated before each warehouse write</h2><div class="flow"><div class="node"><b>Sentiment</b><p>positive · negative · neutral</p></div><div class="node"><b>Score</b><p>Numeric range −1 to +1</p></div><div class="node"><b>Topic</b><p>One of six permitted topics</p></div><div class="node"><b>Issue</b><p>At most six words, or null</p></div></div><footer>Captured 13 November 2026 from ZOMATO.AI.REVIEW_ENRICHED joined to STAGING.STG_REVIEWS. Rendered evidence view of saved warehouse results. The sentiment score is model output, not a calibrated probability or validated accuracy measure.</footer>''')

rows = ''.join('<tr>' + ''.join('<td>'+html.escape(str(row[k]))+'</td>' for k in ['CITY','TOPIC','SENTIMENT_LABEL','REVIEWS','AVG_SENTIMENT_SCORE','FLAGGED_ISSUES'])+'</tr>' for row in evidence['review_mart'])
page('review-mart.html', 'Verified review insights mart', '''<div class="eyebrow">Feature 01 · downstream dbt mart</div><h1>A small enriched sample,<br>with a traceable analytics grain</h1><p class="lead">MART_REVIEW_INSIGHTS groups the enriched review sample by city, topic and sentiment label. Five rows are a functional demonstration, not a customer-wide sentiment estimate.</p><div style="margin-top:35px"><table><thead><tr><th>City</th><th>Topic</th><th>Sentiment</th><th>Reviews</th><th>Avg. score</th><th>Flagged issues</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><div class="stats"><div class="stat"><strong>5</strong><span>enriched reviews saved</span></div><div class="stat"><strong>12</strong><span>AI data checks passed</span></div><div class="stat"><strong>3</strong><span>observed sentiment classes</span></div><div class="stat"><strong>1</strong><span>non-null key issue</span></div></div><footer>Saved Snowflake query output · 13 November 2026. Data lineage: S3 → RAW.REVIEWS → STAGING.STG_REVIEWS → AI.REVIEW_ENRICHED → MARTS.MART_REVIEW_INSIGHTS.</footer>''')
